binary-search.code:
// lo + (hi - lo) / 2 avoids the overflow that (lo + hi) / 2 can hit.
static int search(int[] a, int target) {
    int lo = 0, hi = a.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

// Binary search on the answer: find the smallest capacity that works.
// The predicate must be monotonic — false...false,true...true.
static int minCapacity(int lo, int hi) {
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid;   // keep mid as a candidate
        else lo = mid + 1;
    }
    return lo;
}

