static class ListNode { int val; ListNode next; ListNode(int v) { val = v; } }

// Reverse: walk forward rewiring each next pointer backwards.
static ListNode reverse(ListNode head) {
    ListNode prev = null;
    while (head != null) {
        ListNode next = head.next;   // save before clobbering
        head.next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

// Floyd: slow moves 1, fast moves 2. If they meet there is a cycle.
// Reset one to head and advance both by 1 to find the cycle entry.
static ListNode cycleStart(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next; fast = fast.next.next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) { slow = slow.next; fast = fast.next; }
            return slow;
        }
    }
    return null;
}

