// BST invariant: everything left < node < everything right — and that must
// hold against inherited bounds, not just the immediate parent. Checking
// only the parent is the classic wrong answer.
static boolean isValid(TreeNode r, Long lo, Long hi) {
    if (r == null) return true;
    if (lo != null && r.val <= lo) return false;
    if (hi != null && r.val >= hi) return false;
    return isValid(r.left, lo, (long) r.val) && isValid(r.right, (long) r.val, hi);
}

static TreeNode insert(TreeNode r, int v) {
    if (r == null) return new TreeNode(v);
    if (v < r.val) r.left = insert(r.left, v);
    else if (v > r.val) r.right = insert(r.right, v);
    return r;
}

// LCA in a BST: the first node that splits the two values.
static TreeNode lca(TreeNode r, int p, int q) {
    while (r != null) {
        if (p < r.val && q < r.val) r = r.left;
        else if (p > r.val && q > r.val) r = r.right;
        else return r;
    }
    return null;
}

