// Kth largest: keep a min-heap of size k. O(n log k), better than sorting.
static int kthLargest(int[] nums, int k) {
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int n : nums) {
        pq.offer(n);
        if (pq.size() > k) pq.poll();   // evict the smallest
    }
    return pq.peek();
}

