// Two Sum: store what you've seen, look for the complement. One pass, O(n).
static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();   // value -> index
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);
        if (j != null) return new int[]{j, i};
        seen.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

// Subarray sum equals K: count prefix sums seen so far.
// The seed count.put(0, 1) accounts for a prefix that is itself the answer.
static int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    count.put(0, 1);
    int sum = 0, res = 0;
    for (int n : nums) {
        sum += n;
        res += count.getOrDefault(sum - k, 0);
        count.merge(sum, 1, Integer::sum);
    }
    return res;
}

greedy.code:
// Activity selection / non-overlapping intervals: sort by END time.
// Sorting by start or by duration both fail — the proof is that finishing
// earliest leaves the most room for everything after it.
static int maxNonOverlapping(int[][] intervals) {
    Arrays.sort(intervals, Comparator.comparingInt(x -> x[1]));
    int count = 0, lastEnd = Integer.MIN_VALUE;
    for (int[] iv : intervals) {
        if (iv[0] >= lastEnd) { count++; lastEnd = iv[1]; }
    }
    return count;
}

// Jump game: track the furthest index reachable so far.
static boolean canJump(int[] nums) {
    int reach = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i > reach) return false;
        reach = Math.max(reach, i + nums[i]);
    }
    return true;
}

