// BFS gives shortest path in an UNWEIGHTED graph. Mark visited on enqueue,
// not on dequeue, or nodes get queued many times.
static int[] bfs(List<List<Integer>> adj, int src, int n) {
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    Queue<Integer> q = new ArrayDeque<>();
    dist[src] = 0; q.offer(src);
    while (!q.isEmpty()) {
        int u = q.poll();
        for (int v : adj.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.offer(v); }
    }
    return dist;
}

// Kahn's topological sort. If fewer than n nodes come out, there is a cycle.
static List<Integer> topoSort(List<List<Integer>> adj, int n) {
    int[] indeg = new int[n];
    for (int u = 0; u < n; u++) for (int v : adj.get(u)) indeg[v]++;
    Queue<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.offer(i);
    List<Integer> order = new ArrayList<>();
    while (!q.isEmpty()) {
        int u = q.poll(); order.add(u);
        for (int v : adj.get(u)) if (--indeg[v] == 0) q.offer(v);
    }
    return order.size() == n ? order : List.of();   // empty => cycle
}

dynamic-programming.code:
// The progression to practise on every DP: recursion -> memo -> table -> O(1) space.

// 1. Top-down (memoised recursion).
static int robMemo(int[] a, int i, Integer[] memo) {
    if (i >= a.length) return 0;
    if (memo[i] != null) return memo[i];
    return memo[i] = Math.max(a[i] + robMemo(a, i + 2, memo), robMemo(a, i + 1, memo));
}

// 2. Bottom-up table.
static int robTab(int[] a) {
    int n = a.length;
    int[] dp = new int[n + 2];
    for (int i = n - 1; i >= 0; i--) dp[i] = Math.max(a[i] + dp[i + 2], dp[i + 1]);
    return dp[0];
}

// 3. Rolling — only the last two states are ever read.
static int rob(int[] a) {
    int take = 0, skip = 0;
    for (int i = a.length - 1; i >= 0; i--) {
        int cur = Math.max(a[i] + skip, take);
        skip = take; take = cur;
    }
    return take;
}

// 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used once.
int[] dp = new int[cap + 1];
for (int i = 0; i < n; i++)
    for (int w = cap; w >= wt[i]; w--)
        dp[w] = Math.max(dp[w], val[i] + dp[w - wt[i]]);

