// A trie trades memory for prefix queries in O(length) regardless of how
// many words are stored.
static class Trie {
    private final Trie[] next = new Trie[26];
    private boolean end;

    void insert(String w) {
        Trie cur = this;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (cur.next[i] == null) cur.next[i] = new Trie();
            cur = cur.next[i];
        }
        cur.end = true;
    }

    private Trie walk(String w) {
        Trie cur = this;
        for (char c : w.toCharArray()) {
            cur = cur.next[c - 'a'];
            if (cur == null) return null;
        }
        return cur;
    }

    boolean search(String w)     { Trie n = walk(w); return n != null && n.end; }
    boolean startsWith(String p) { return walk(p) != null; }
}

